#!/usr/bin/env python3
"""Reviewed source deployment; no credentials, no message replay, no gateway restart."""
import argparse,base64,datetime,fcntl,gzip,hashlib,json,os,pathlib,pwd,shutil,sqlite3,subprocess,tempfile,time,urllib.request,urllib.error
BUNDLE=''
ROOTS={'application':'/opt/umraniye-osint-deneme','browser':'/opt/umraniye-osint-browser','instagram-api':'/opt/umraniye-osint-instagram-api','instagram-media':'/opt/umraniye-osint-igmedia','x-shadow':'/opt/umraniye-osint-x-twscrape-deneme','facebook-shadow':'/opt/umraniye-osint-facebook-fbgql-deneme'}
APP='umraniye-osint-deneme.service'
TIMERS=['umraniye-osint-sirali.timer','umraniye-osint-browser.timer','umraniye-osint-browser-x.timer','umraniye-osint-browser-facebook.timer','umraniye-osint-browser-instagram.timer','umraniye-osint-dha-deneme.timer','umraniye-osint-facebook-fbgql-deneme.timer','umraniye-osint-instagram-akilli.timer','umraniye-osint-instagram-api.timer','umraniye-osint-instagram-medya.timer','umraniye-osint-x-twscrape-deneme.timer']
SERVICES=[t.replace('.timer','.service') for t in TIMERS]+['umraniye-osint-x-backup-publish.service','umraniye-osint-facebook-supplement-publish.service']
def run(args,check=True,**kw):return subprocess.run(args,check=check,capture_output=True,text=True,**kw)
def prop(unit,key):return run(['systemctl','show',unit,'-p',key,'--value'],False).stdout.strip()
def active(unit):return prop(unit,'ActiveState') in ('active','activating','reloading')
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
def safe(p):
    for q in [p,*p.parents]:
        if q.is_symlink():raise RuntimeError('symlink_path_rejected: '+str(p))
def write(p,data,mode,uid,gid):
    safe(p);p.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix='.reviewed-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),mode);os.fchown(f.fileno(),uid,gid)
        os.replace(tmp,p)
    finally:pathlib.Path(tmp).unlink(missing_ok=True)
def health(port):
    try:
        # Reject redirect following: canonical HTTPS may be inaccessible from the origin host.
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self,*a,**kw):return None
        opener=urllib.request.build_opener(NoRedirect)
        r=opener.open('http://127.0.0.1:'+str(port)+'/giris',timeout=5)
        return r.status==200
    except urllib.error.HTTPError as e:return e.code in (301,302,303,307,308)
    except Exception:return False
def restore(backup,manifest):
    for item in reversed(manifest):
        p=pathlib.Path(item['path'])
        if item['existed']:write(p,(backup/'files'/item['key']).read_bytes(),item['mode'],item['uid'],item['gid'])
        else:safe(p);p.unlink(missing_ok=True)
def main():
    parser=argparse.ArgumentParser();parser.add_argument('--apply',action='store_true');args=parser.parse_args()
    if os.geteuid()!=0:raise RuntimeError('sudo_required')
    lock=open('/run/osint-reviewed-release.lock','w');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    bundle=json.loads(gzip.decompress(base64.b64decode(BUNDLE)));user=pwd.getpwnam('osintdeneme')
    targets=[];drift=[]
    for key,item in bundle['files'].items():
        prefix,relative=key.split('/',1)
        if prefix not in ROOTS or '..' in pathlib.PurePosixPath(relative).parts:raise RuntimeError('invalid_bundle_path')
        p=pathlib.Path(ROOTS[prefix])/relative;safe(p)
        if digest(p)!=item['before']:drift.append(key)
        data=base64.b64decode(item['content'])
        if hashlib.sha256(data).hexdigest()!=item['after']:raise RuntimeError('payload_hash_mismatch')
        targets.append((key,p,data))
    if drift:raise RuntimeError('source_versions_changed_no_install: '+', '.join(drift))
    if not active(APP) or not health(3001) or not health(3000):raise RuntimeError('existing_application_not_healthy_no_install')
    # A schema-only canary already passed. Recheck every previously applied migration checksum.
    dbpath=pathlib.Path('/var/lib/umraniye-osint-deneme/osint.sqlite');safe(dbpath)
    with sqlite3.connect('file:'+str(dbpath)+'?mode=ro',uri=True) as db:
        for name,h in db.execute('SELECT name,checksum FROM local_migrations'):
            item=bundle['files'].get('application/drizzle/'+name)
            actual=item['after'] if item else digest(pathlib.Path(ROOTS['application'])/'drizzle'/name)
            if actual!=h:raise RuntimeError('applied_migration_checksum_changed: '+name)
    if not args.apply:
        print(json.dumps({'result':'reviewed_release_preflight_passed','files':len(targets),'liveFilesChanged':False,'messagesSent':0}));return
    stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    backupRoot=pathlib.Path('/var/backups/umraniye-osint-reviewed');safe(backupRoot);backupRoot.mkdir(mode=0o700,exist_ok=True)
    if backupRoot.stat().st_uid!=0:raise RuntimeError('backup_directory_not_root_owned')
    os.chmod(backupRoot,0o700)
    backup=backupRoot/('provider-health-'+stamp);backup.mkdir(mode=0o700)
    manifest=[]
    for key,p,data in targets:
        st=p.stat() if p.exists() else None
        item={'key':key,'path':str(p),'existed':bool(st),'uid':st.st_uid if st else user.pw_uid,'gid':st.st_gid if st else user.pw_gid,'mode':st.st_mode&0o777 if st else 0o644}
        if st:
            out=backup/'files'/key;out.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,out)
        manifest.append(item)
    (backup/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2));os.chmod(backup/'manifest.json',0o600)
    rollback='''#!/usr/bin/env python3
import importlib.util,pathlib,json,subprocess,time,fcntl
p=pathlib.Path(__file__).parent
s=importlib.util.spec_from_file_location('installer',p/'installer.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
lock=open('/run/osint-reviewed-release.lock','w');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
timers={t:m.active(t) for t in m.TIMERS}
try:
 for t,on in timers.items():
  if on:m.run(['systemctl','stop',t])
 end=time.monotonic()+300
 while any(m.active(s) for s in m.SERVICES):
  if time.monotonic()>end:raise RuntimeError('collector_busy_no_rollback')
  time.sleep(2)
 subprocess.run(['systemctl','stop',m.APP],check=True)
 try:m.restore(p,json.loads((p/'manifest.json').read_text()))
 finally:subprocess.run(['systemctl','start',m.APP],check=True)
finally:
 for t,on in timers.items():
  if on:m.run(['systemctl','start',t],False)
print('Kod geri alındı. Yeni haberleri korumak için veritabanı geri yüklenmedi.')
'''
    shutil.copy2(__file__,backup/'installer.py');(backup/'geri-al.py').write_text(rollback)
    gatewayBefore={u:prop(u,'ExecMainStartTimestampMonotonic') for u in ['umraniye-osint.service','umraniye-telegram.service']}
    timerStates={u:active(u) for u in TIMERS};stopped=False;installed=False
    try:
        for t,on in timerStates.items():
            if on:run(['systemctl','stop',t])
        deadline=time.monotonic()+300
        next_notice=0
        while any(active(s) for s in SERVICES):
            if time.monotonic()>deadline:raise RuntimeError('existing_collector_round_busy_no_install')
            if time.monotonic()>=next_notice:print('Mevcut tarama turunun bitmesi bekleniyor; tarayıcılar zorla kapatılmıyor.',flush=True);next_notice=time.monotonic()+30
            time.sleep(2)
        # Recheck immediately before stopping: concurrent operators must not be overwritten.
        for key,p,data in targets:
            if digest(p)!=bundle['files'][key]['before']:raise RuntimeError('source_changed_during_preflight')
        print('Yedek hazır. Yalnız mevcut uygulama kısa süreli yeniden başlatılacak.',flush=True)
        stopped=True;run(['systemctl','stop',APP],timeout=120)
        with sqlite3.connect('file:'+str(dbpath)+'?mode=ro',uri=True) as src,sqlite3.connect(backup/'osint.sqlite') as dst:src.backup(dst)
        os.chmod(backup/'osint.sqlite',0o600)
        installed=True
        for (key,p,data),meta in zip(targets,manifest):write(p,data,meta['mode'],meta['uid'],meta['gid'])
        run(['python3','/opt/umraniye-osint-instagram-api/publish_status.py'],timeout=15)
        run(['systemctl','start',APP],timeout=120)
        for _ in range(60):
            if active(APP) and health(3001) and health(3000):break
            time.sleep(1)
        else:raise RuntimeError('new_application_health_failed')
        for u,before in gatewayBefore.items():
            if prop(u,'ExecMainStartTimestampMonotonic')!=before:raise RuntimeError('unrelated_service_changed')
        report={'result':'provider_health_reporting_installed','files':len(targets),'applicationActive':True,'localPort3001Verified':True,'gatewayPort3000Verified':True,'gatewayRestarted':False,'telegramServiceRestarted':False,'telegramSettingsChanged':False,'historicalReplayRequested':False,'retentionMonths':6,'newTimers':0,'browserProfilesChanged':False,'externalBrowserVerified':False,'newLiveSocialPostVerified':False,'databaseBackup':True,'schemaMigration':'none; schema unchanged','backup':str(backup),'rollback':'sudo python3 '+str(backup/'geri-al.py')}
        report['changedFiles']=[str(p) for _,p,_ in targets]
        (backup/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False,indent=2))
    except Exception:
        if installed:
            run(['systemctl','stop',APP],False);restore(backup,manifest)
        if stopped:run(['systemctl','start',APP],False)
        raise
    finally:
        for t,on in timerStates.items():
            if on:run(['systemctl','start',t],False)
        if any(active(t)!=on for t,on in timerStates.items()):raise RuntimeError('timer_restore_requires_attention')
if __name__=='__main__':
    try:main()
    except Exception as e:print('KURULAMADI: '+str(e));raise SystemExit(1)
